import { existsSync, mkdirSync, writeFileSync, readFileSync } from 'node:fs'
import { dirname } from 'node:path'

const newFiles = {"src/features/stickers/packs.ts":"import { supabase } from '../../lib/supabase'\nimport { shrink } from './stickers'\n\nexport const MAX_PACKS = 20\nexport const MAX_ITEMS = 120\n\nexport interface PackItem { id: string; path: string; position: number }\nexport interface Pack { id: string; owner_id: string; title: string; short_code: string; owner_name: string | null; items: PackItem[] }\nexport interface PackInfo { id: string; title: string; code: string; owner_name: string | null; mine: boolean; subscribed: boolean; items: string[] }\n\ninterface PackRow {\n  id: string; owner_id: string; title: string; short_code: string\n  sticker_pack_items: PackItem[] | null\n}\n\nexport function errMsg(e: unknown): string {\n  if (e instanceof Error) return e.message\n  if (e && typeof e === 'object' && 'message' in e) return String((e as { message: unknown }).message)\n  return String(e)\n}\n\nexport function friendlyPackError(msg: string): string {\n  if (msg.includes('pack limit')) return `Можно создать не больше ${MAX_PACKS} наборов.`\n  if (msg.includes('item limit')) return `В наборе не больше ${MAX_ITEMS} стикеров.`\n  if (msg.includes('sub limit')) return 'Добавлено слишком много наборов.'\n  if (msg.includes('pack not found')) return 'Набор с таким кодом не найден.'\n  if (msg.includes('duplicate key')) return 'Такой стикер уже есть в наборе.'\n  if (msg.includes('sticker_packs') || msg.includes('schema cache') || msg.includes('pack_by_')) return 'Наборы не настроены: выполните SQL 0017.'\n  return msg\n}\n\nexport const stickersWord = (n: number): string => {\n  const a = n % 100, b = n % 10\n  if (a >= 11 && a <= 14) return 'стикеров'\n  if (b === 1) return 'стикер'\n  if (b >= 2 && b <= 4) return 'стикера'\n  return 'стикеров'\n}\n\nexport async function meId(): Promise<string> {\n  const { data } = await supabase.auth.getSession()\n  const id = data.session?.user.id\n  if (!id) throw new Error('not authenticated')\n  return id\n}\n\nexport async function listPacks(): Promise<Pack[]> {\n  const { data, error } = await supabase.from('sticker_packs')\n    .select('id, owner_id, title, short_code, sticker_pack_items(id, path, position)')\n    .order('created_at', { ascending: true })\n  if (error) throw error\n  const rows = (data ?? []) as unknown as PackRow[]\n  const owners = [...new Set(rows.map((r) => r.owner_id))]\n  const names: Record<string, string | null> = {}\n  if (owners.length > 0) {\n    const pr = await supabase.from('profiles').select('id, display_name').in('id', owners)\n    for (const p of (pr.data ?? []) as { id: string; display_name: string | null }[]) names[p.id] = p.display_name\n  }\n  return rows.map((r) => ({\n    id: r.id, owner_id: r.owner_id, title: r.title, short_code: r.short_code,\n    owner_name: names[r.owner_id] ?? null,\n    items: [...(r.sticker_pack_items ?? [])].sort((a, b) => a.position - b.position),\n  }))\n}\n\nexport async function createPack(title: string): Promise<Pack> {\n  const uid = await meId()\n  const { data, error } = await supabase.from('sticker_packs').insert({ title: title.trim() }).select('id, owner_id, title, short_code').single()\n  if (error) throw error\n  const r = data as { id: string; owner_id: string; title: string; short_code: string }\n  return { ...r, owner_name: null, items: [], owner_id: r.owner_id || uid }\n}\n\nexport async function renamePack(id: string, title: string): Promise<void> {\n  const { error } = await supabase.from('sticker_packs').update({ title: title.trim() }).eq('id', id)\n  if (error) throw error\n}\n\nexport async function deletePack(id: string): Promise<void> {\n  const { error } = await supabase.from('sticker_packs').delete().eq('id', id)\n  if (error) throw error\n}\n\nexport async function uploadStickerFile(file: File): Promise<string> {\n  if (!/^image\\/(png|webp|gif|jpeg)$/.test(file.type)) throw new Error('Подходят PNG, WebP, GIF и JPEG.')\n  const uid = await meId()\n  const s = await shrink(file)\n  if (s.blob.size > 2 * 1024 * 1024) throw new Error('Стикер больше 2 МБ.')\n  const path = `${uid}/${crypto.randomUUID()}.${s.ext}`\n  const up = await supabase.storage.from('stickers').upload(path, s.blob, { contentType: s.type })\n  if (up.error) throw up.error\n  return path\n}\n\nexport async function addItem(packId: string, path: string, position: number): Promise<PackItem> {\n  const { data, error } = await supabase.from('sticker_pack_items').insert({ pack_id: packId, path, position }).select('id, path, position').single()\n  if (error) throw error\n  return data as PackItem\n}\n\nexport async function removeItem(id: string): Promise<void> {\n  const { error } = await supabase.from('sticker_pack_items').delete().eq('id', id)\n  if (error) throw error\n}\n\nexport async function packByCode(code: string): Promise<PackInfo | null> {\n  const { data, error } = await supabase.rpc('pack_by_code', { p_code: code })\n  if (error) throw error\n  return (data as PackInfo | null) ?? null\n}\n\nexport async function packByPath(path: string): Promise<PackInfo | null> {\n  const { data, error } = await supabase.rpc('pack_by_path', { p_path: path })\n  if (error) throw error\n  return (data as PackInfo | null) ?? null\n}\n\nexport async function subscribePack(code: string): Promise<void> {\n  const { error } = await supabase.rpc('subscribe_pack', { p_code: code })\n  if (error) throw error\n}\n\nexport async function unsubscribePack(packId: string): Promise<void> {\n  const uid = await meId()\n  const { error } = await supabase.from('sticker_pack_subs').delete().eq('pack_id', packId).eq('user_id', uid)\n  if (error) throw error\n}\n\n// Код из ссылки или просто код.\nexport function parseCode(input: string): string {\n  const t = input.trim()\n  const m = /pack=([0-9a-fA-F]+)/.exec(t)\n  return (m ? m[1] : t.replace(/[^0-9a-zA-Z]/g, '')).toLowerCase()\n}\n","src/features/stickers/PackPreview.tsx":"import { useState } from 'react'\nimport { createPortal } from 'react-dom'\nimport { Check, X } from 'lucide-react'\nimport { stickerUrl } from './stickers'\nimport { errMsg, friendlyPackError, stickersWord, subscribePack, unsubscribePack, type PackInfo } from './packs'\n\n// Просмотр чужого набора с кнопкой «Добавить набор».\nexport default function PackPreview({ info, onClose, onChanged }: { info: PackInfo; onClose: () => void; onChanged?: () => void }) {\n  const [added, setAdded] = useState(info.subscribed)\n  const [busy, setBusy] = useState(false)\n  const [err, setErr] = useState<string | null>(null)\n\n  async function toggle() {\n    setBusy(true); setErr(null)\n    try {\n      if (added) await unsubscribePack(info.id); else await subscribePack(info.code)\n      setAdded(!added)\n      onChanged?.()\n    } catch (e) { setErr(friendlyPackError(errMsg(e))) } finally { setBusy(false) }\n  }\n\n  return createPortal(\n    <div data-sticker-modal className=\"fixed inset-0 z-[70] flex items-center justify-center bg-black/70 p-4\" onClick={(e) => { e.stopPropagation(); onClose() }}>\n      <div className=\"flex max-h-[85vh] w-full max-w-md flex-col overflow-hidden rounded-3xl border border-line bg-bg2 shadow-2xl\" onClick={(e) => e.stopPropagation()}>\n        <div className=\"flex shrink-0 items-start gap-3 p-5 pb-3\">\n          <div className=\"min-w-0 flex-1\">\n            <h3 className=\"truncate text-lg font-semibold\">{info.title}</h3>\n            <p className=\"truncate text-sm text-muted\">\n              {info.items.length} {stickersWord(info.items.length)}{info.owner_name ? ` · ${info.owner_name}` : ''}\n            </p>\n          </div>\n          <button type=\"button\" onClick={onClose} className=\"rounded-xl p-1.5 text-muted transition hover:bg-surface hover:text-text\"><X size={18} /></button>\n        </div>\n        <div className=\"min-h-0 flex-1 overflow-y-auto px-5 pb-3\">\n          <div className=\"grid grid-cols-4 gap-2\">\n            {info.items.map((p) => (\n              <div key={p} className=\"aspect-square rounded-2xl bg-surface p-1.5\">\n                <img src={stickerUrl(p)} alt=\"\" loading=\"lazy\" draggable={false} className=\"h-full w-full object-contain\" />\n              </div>\n            ))}\n          </div>\n        </div>\n        <div className=\"shrink-0 border-t border-line p-4\">\n          {err && <p className=\"pb-2 text-xs text-pink\">{err}</p>}\n          {info.mine ? (\n            <p className=\"py-2 text-center text-sm text-muted\">Это ваш набор</p>\n          ) : (\n            <button type=\"button\" disabled={busy} onClick={() => void toggle()}\n              className={`flex w-full items-center justify-center gap-2 rounded-2xl py-3 text-sm font-semibold transition disabled:opacity-60 ${\n                added ? 'bg-surface text-text hover:text-pink' : 'bg-accent text-on-accent hover:opacity-90'}`}>\n              {added ? <><Check size={16} />Добавлен · убрать</> : 'Добавить набор'}\n            </button>\n          )}\n        </div>\n      </div>\n    </div>,\n    document.body,\n  )\n}\n","src/features/stickers/PackManager.tsx":"import { useEffect, useRef, useState, type FormEvent } from 'react'\nimport { createPortal } from 'react-dom'\nimport { ArrowLeft, Check, Loader2, Plus, Share2, Sticker as StickerIcon, X } from 'lucide-react'\nimport { stickerUrl } from './stickers'\nimport {\n  MAX_ITEMS, MAX_PACKS, addItem, createPack, deletePack, errMsg, friendlyPackError, listPacks, meId, packByCode, parseCode,\n  removeItem, renamePack, stickersWord, unsubscribePack, uploadStickerFile, type Pack, type PackInfo,\n} from './packs'\nimport PackPreview from './PackPreview'\n\n// Окно «Стикеры»: свои и добавленные наборы, создание, переименование, добавление стикеров.\nexport default function PackManager({ onClose }: { onClose: () => void }) {\n  const [packs, setPacks] = useState<Pack[]>([])\n  const [uid, setUid] = useState('')\n  const [loaded, setLoaded] = useState(false)\n  const [sel, setSel] = useState<string | null>(null)\n  const [creating, setCreating] = useState(false)\n  const [newTitle, setNewTitle] = useState('')\n  const [code, setCode] = useState('')\n  const [preview, setPreview] = useState<PackInfo | null>(null)\n  const [busy, setBusy] = useState(false)\n  const [err, setErr] = useState<string | null>(null)\n  const [copied, setCopied] = useState(false)\n  const [confirmDel, setConfirmDel] = useState(false)\n  const [title, setTitle] = useState('')\n  const fileRef = useRef<HTMLInputElement>(null)\n\n  async function reload() {\n    try { setPacks(await listPacks()); setErr(null) }\n    catch (e) { setErr(friendlyPackError(errMsg(e))) }\n    finally { setLoaded(true) }\n  }\n\n  useEffect(() => {\n    let alive = true\n    void meId().then((id) => { if (alive) setUid(id) }).catch(() => undefined)\n    void listPacks().then((p) => { if (alive) { setPacks(p); setLoaded(true) } })\n      .catch((e) => { if (alive) { setErr(friendlyPackError(errMsg(e))); setLoaded(true) } })\n    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') { e.stopPropagation(); onClose() } }\n    document.addEventListener('keydown', onKey, true)\n    return () => { alive = false; document.removeEventListener('keydown', onKey, true) }\n  }, [onClose])\n\n  const mine = packs.filter((p) => p.owner_id === uid)\n  const added = packs.filter((p) => p.owner_id !== uid)\n  const cur = packs.find((p) => p.id === sel) ?? null\n  const isMine = !!cur && cur.owner_id === uid\n\n  useEffect(() => { setTitle(cur?.title ?? ''); setConfirmDel(false); setCopied(false) }, [cur?.id, cur?.title])\n\n  function patchPack(id: string, fn: (p: Pack) => Pack) { setPacks((prev) => prev.map((p) => (p.id === id ? fn(p) : p))) }\n\n  async function onCreate(e: FormEvent) {\n    e.preventDefault()\n    const t = newTitle.trim()\n    if (!t || busy) return\n    setBusy(true); setErr(null)\n    try {\n      const p = await createPack(t)\n      setPacks((prev) => [...prev, p]); setSel(p.id); setCreating(false); setNewTitle('')\n    } catch (e2) { setErr(friendlyPackError(errMsg(e2))) } finally { setBusy(false) }\n  }\n\n  async function onFindCode(e: FormEvent) {\n    e.preventDefault()\n    const c = parseCode(code)\n    if (!c || busy) return\n    setBusy(true); setErr(null)\n    try {\n      const info = await packByCode(c)\n      if (!info) setErr('Набор с таким кодом не найден.')\n      else { setPreview(info); setCode('') }\n    } catch (e2) { setErr(friendlyPackError(errMsg(e2))) } finally { setBusy(false) }\n  }\n\n  async function saveTitle() {\n    if (!cur || !isMine) return\n    const t = title.trim()\n    if (!t) { setTitle(cur.title); return }\n    if (t === cur.title) return\n    try { await renamePack(cur.id, t); patchPack(cur.id, (p) => ({ ...p, title: t })) }\n    catch (e) { setErr(friendlyPackError(errMsg(e))); setTitle(cur.title) }\n  }\n\n  async function onFiles(files: FileList | null) {\n    const list = Array.from(files ?? [])\n    if (fileRef.current) fileRef.current.value = ''\n    if (!cur || list.length === 0) return\n    setBusy(true); setErr(null)\n    try {\n      let pos = cur.items.reduce((m, i) => Math.max(m, i.position), -1) + 1\n      for (const f of list) {\n        const path = await uploadStickerFile(f)\n        const it = await addItem(cur.id, path, pos++)\n        patchPack(cur.id, (p) => ({ ...p, items: [...p.items, it] }))\n      }\n    } catch (e) { setErr(friendlyPackError(errMsg(e))) } finally { setBusy(false) }\n  }\n\n  async function onRemoveItem(packId: string, itemId: string) {\n    const before = packs.find((p) => p.id === packId)?.items ?? []\n    patchPack(packId, (p) => ({ ...p, items: p.items.filter((i) => i.id !== itemId) }))\n    try { await removeItem(itemId) } catch { patchPack(packId, (p) => ({ ...p, items: before })) }\n  }\n\n  async function onDelete() {\n    if (!cur) return\n    if (!confirmDel) { setConfirmDel(true); return }\n    try {\n      if (isMine) await deletePack(cur.id); else await unsubscribePack(cur.id)\n      setPacks((prev) => prev.filter((p) => p.id !== cur.id)); setSel(null)\n    } catch (e) { setErr(friendlyPackError(errMsg(e))) }\n  }\n\n  async function share() {\n    if (!cur) return\n    try { await navigator.clipboard.writeText(cur.short_code); setCopied(true); setTimeout(() => setCopied(false), 2000) }\n    catch { setErr(`Код набора: ${cur.short_code}`) }\n  }\n\n  const row = (p: Pack) => (\n    <button key={p.id} type=\"button\" onClick={() => { setSel(p.id); setErr(null) }}\n      className={`flex w-full items-center gap-3 rounded-2xl p-2 text-left transition ${sel === p.id ? 'bg-surface' : 'hover:bg-surface/60'}`}>\n      <span className=\"flex h-11 w-11 shrink-0 items-center justify-center overflow-hidden rounded-xl bg-bg p-1 text-muted\">\n        {p.items[0] ? <img src={stickerUrl(p.items[0].path)} alt=\"\" className=\"h-full w-full object-contain\" /> : <StickerIcon size={18} />}\n      </span>\n      <span className=\"min-w-0\">\n        <span className=\"block truncate text-sm font-semibold\">{p.title}</span>\n        <span className=\"block text-xs text-muted\">{p.items.length} {stickersWord(p.items.length)}</span>\n      </span>\n    </button>\n  )\n\n  return createPortal(\n    <div data-sticker-modal className=\"fixed inset-0 z-[60] flex items-center justify-center bg-black/70 md:p-6\" onClick={onClose}>\n      <div className=\"flex h-full w-full max-w-4xl flex-col overflow-hidden bg-bg2 md:h-[36rem] md:rounded-3xl md:border md:border-line\" onClick={(e) => e.stopPropagation()}>\n        <div className=\"flex shrink-0 items-center justify-between border-b border-line px-5 py-3\">\n          <h2 className=\"font-semibold\">Стикеры</h2>\n          <button type=\"button\" onClick={onClose} className=\"rounded-xl p-1.5 text-muted transition hover:bg-surface hover:text-text\"><X size={18} /></button>\n        </div>\n        <div className=\"flex min-h-0 flex-1\">\n          <aside className={`${sel ? 'hidden md:flex' : 'flex'} min-h-0 w-full shrink-0 flex-col gap-2 border-line p-3 md:w-72 md:border-r`}>\n            {creating ? (\n              <form onSubmit={(e) => void onCreate(e)} className=\"flex shrink-0 gap-2\">\n                <input autoFocus value={newTitle} maxLength={40} onChange={(e) => setNewTitle(e.target.value)} placeholder=\"Название набора\"\n                  className=\"min-w-0 flex-1 rounded-2xl bg-surface px-4 py-2.5 text-sm outline-none placeholder:text-muted\" />\n                <button type=\"submit\" disabled={!newTitle.trim() || busy} className=\"rounded-2xl bg-accent px-3 text-on-accent disabled:opacity-40\"><Check size={18} /></button>\n                <button type=\"button\" onClick={() => { setCreating(false); setNewTitle('') }} className=\"rounded-2xl bg-surface px-3 text-muted hover:text-text\"><X size={18} /></button>\n              </form>\n            ) : (\n              <button type=\"button\" disabled={mine.length >= MAX_PACKS} onClick={() => setCreating(true)}\n                className=\"flex shrink-0 items-center justify-center gap-2 rounded-2xl bg-surface py-3 text-sm font-semibold transition hover:text-accent disabled:opacity-50\">\n                <Plus size={16} />Новый набор\n              </button>\n            )}\n            <form onSubmit={(e) => void onFindCode(e)} className=\"flex shrink-0 gap-2\">\n              <input value={code} onChange={(e) => setCode(e.target.value)} placeholder=\"Код или ссылка набора\"\n                className=\"min-w-0 flex-1 rounded-2xl bg-surface px-4 py-2 text-sm outline-none placeholder:text-muted\" />\n              <button type=\"submit\" disabled={!code.trim() || busy} title=\"Найти набор\" className=\"rounded-2xl bg-surface px-3 text-accent transition hover:bg-bg disabled:opacity-40\">\n                {busy && !creating ? <Loader2 size={16} className=\"animate-spin\" /> : <Plus size={16} />}\n              </button>\n            </form>\n            <div className=\"min-h-0 flex-1 overflow-y-auto\">\n              {!loaded && <div className=\"h-14 animate-pulse rounded-2xl bg-surface\" />}\n              {loaded && (\n                <>\n                  <h3 className=\"px-2 pb-1 pt-2 text-xs font-semibold text-muted\">Мои · {mine.length} из {MAX_PACKS}</h3>\n                  {mine.length === 0 && <p className=\"px-2 py-2 text-xs text-muted\">Создайте свой первый набор.</p>}\n                  {mine.map(row)}\n                  {added.length > 0 && <h3 className=\"px-2 pb-1 pt-4 text-xs font-semibold text-muted\">Добавленные</h3>}\n                  {added.map(row)}\n                </>\n              )}\n            </div>\n          </aside>\n\n          <section className={`${sel ? 'flex' : 'hidden md:flex'} min-h-0 min-w-0 flex-1 flex-col`}>\n            {!cur ? (\n              <div className=\"m-auto px-6 text-center text-sm text-muted\">\n                {err ?? 'Выберите набор слева или создайте свой.'}\n              </div>\n            ) : (\n              <>\n                <div className=\"min-h-0 flex-1 overflow-y-auto p-5\">\n                  <div className=\"flex items-start gap-2\">\n                    <button type=\"button\" onClick={() => setSel(null)} className=\"mt-1 rounded-xl p-1.5 text-muted hover:bg-surface hover:text-text md:hidden\"><ArrowLeft size={18} /></button>\n                    <div className=\"min-w-0 flex-1\">\n                      {isMine ? (\n                        <input value={title} maxLength={40} onChange={(e) => setTitle(e.target.value)} onBlur={() => void saveTitle()}\n                          onKeyDown={(e) => { if (e.key === 'Enter') e.currentTarget.blur() }}\n                          className=\"w-full rounded-xl bg-transparent px-1 text-2xl font-bold outline-none transition hover:bg-surface/60 focus:bg-surface\" />\n                      ) : <h3 className=\"truncate px-1 text-2xl font-bold\">{cur.title}</h3>}\n                      <p className=\"px-1 pt-1 text-sm text-muted\">\n                        {cur.items.length}{isMine ? ` из ${MAX_ITEMS}` : ''} {stickersWord(cur.items.length)} · {isMine ? 'ваш набор' : `от ${cur.owner_name ?? 'пользователя'}`}\n                      </p>\n                    </div>\n                    <button type=\"button\" onClick={() => void share()}\n                      className=\"flex shrink-0 items-center gap-2 rounded-2xl bg-surface px-4 py-2.5 text-sm font-semibold transition hover:text-accent\">\n                      {copied ? <Check size={16} className=\"text-accent\" /> : <Share2 size={16} />}{copied ? 'Код скопирован' : 'Поделиться'}\n                    </button>\n                  </div>\n                  {err && <p className=\"px-1 pt-3 text-xs text-pink\">{err}</p>}\n                  <input ref={fileRef} type=\"file\" multiple accept=\"image/png,image/webp,image/gif,image/jpeg\" className=\"hidden\" onChange={(e) => void onFiles(e.target.files)} />\n                  <div className=\"mt-5 grid grid-cols-4 gap-2 md:grid-cols-6\">\n                    {cur.items.map((it) => (\n                      <div key={it.id} className=\"group relative aspect-square rounded-2xl bg-surface p-2\">\n                        <img src={stickerUrl(it.path)} alt=\"\" loading=\"lazy\" draggable={false} className=\"h-full w-full object-contain\" />\n                        {isMine && (\n                          <button type=\"button\" title=\"Убрать из набора\" onClick={() => void onRemoveItem(cur.id, it.id)}\n                            className=\"absolute right-1 top-1 flex h-5 w-5 items-center justify-center rounded-full bg-bg2/90 text-muted opacity-0 transition hover:text-pink group-hover:opacity-100 max-md:opacity-70\"><X size={12} /></button>\n                        )}\n                      </div>\n                    ))}\n                    {isMine && cur.items.length < MAX_ITEMS && (\n                      <button type=\"button\" disabled={busy} onClick={() => fileRef.current?.click()}\n                        className=\"flex aspect-square items-center justify-center rounded-2xl border border-dashed border-line text-muted transition hover:border-accent hover:text-accent disabled:opacity-60\">\n                        {busy ? <Loader2 size={22} className=\"animate-spin\" /> : <Plus size={22} />}\n                      </button>\n                    )}\n                  </div>\n                  {isMine && <p className=\"px-1 pt-4 text-xs leading-relaxed text-muted\">PNG, WebP или GIF до 2 МБ. Лучше с прозрачным фоном, большие картинки уменьшаются до 512 px. Код набора можно отправить другу, он вставит его в поле «Код или ссылка набора».</p>}\n                </div>\n                <div className=\"flex shrink-0 items-center justify-between gap-3 border-t border-line px-5 py-3 text-sm\">\n                  <span className=\"min-w-0 truncate text-muted\">Код: <span className=\"select-all font-mono text-text\">{cur.short_code}</span></span>\n                  <button type=\"button\" onClick={() => void onDelete()} onBlur={() => setConfirmDel(false)}\n                    className=\"shrink-0 font-medium text-pink transition hover:opacity-80\">\n                    {confirmDel ? 'Точно? Нажмите ещё раз' : isMine ? 'Удалить набор' : 'Убрать из добавленных'}\n                  </button>\n                </div>\n              </>\n            )}\n          </section>\n        </div>\n      </div>\n      {preview && <PackPreview info={preview} onClose={() => setPreview(null)} onChanged={() => void reload()} />}\n    </div>,\n    document.body,\n  )\n}\n","src/features/stickers/StickerTab.tsx":"import { useEffect, useRef, useState } from 'react'\nimport { Clock, Loader2, Plus, Settings2, Star, X } from 'lucide-react'\nimport { addSticker, friendlyStickerError, getRecent, listMine, pushRecent, removeSticker, stickerUrl, type UserSticker } from './stickers'\nimport { errMsg, listPacks, type Pack } from './packs'\nimport PackManager from './PackManager'\n\n// Вкладка «Стикеры»: недавние, избранные и наборы с нижней полосой переключения.\nexport default function StickerTab({ canSend, onSend }: { canSend: boolean; onSend: (path: string) => void }) {\n  const [packs, setPacks] = useState<Pack[]>([])\n  const [mine, setMine] = useState<UserSticker[]>([])\n  const [loaded, setLoaded] = useState(false)\n  const [packsErr, setPacksErr] = useState(false)\n  const [sel, setSel] = useState('')\n  const [manage, setManage] = useState(false)\n  const [busy, setBusy] = useState(false)\n  const [err, setErr] = useState<string | null>(null)\n  const fileRef = useRef<HTMLInputElement>(null)\n\n  async function load() {\n    const [p, m] = await Promise.allSettled([listPacks(), listMine()])\n    if (p.status === 'fulfilled') { setPacks(p.value); setPacksErr(false) } else setPacksErr(true)\n    if (m.status === 'fulfilled') setMine(m.value.filter((s) => s.kind === 'sticker'))\n    setLoaded(true)\n  }\n\n  useEffect(() => {\n    let alive = true\n    void Promise.allSettled([listPacks(), listMine()]).then(([p, m]) => {\n      if (!alive) return\n      if (p.status === 'fulfilled') setPacks(p.value); else setPacksErr(true)\n      if (m.status === 'fulfilled') setMine(m.value.filter((s) => s.kind === 'sticker'))\n      setLoaded(true)\n    })\n    return () => { alive = false }\n  }, [])\n\n  const recent = getRecent('sticker')\n  const cur = sel === 'recent' || sel === 'mine' || packs.some((p) => p.id === sel) ? sel : (recent.length > 0 ? 'recent' : packs.length > 0 ? packs[0].id : 'mine')\n  const pack = packs.find((p) => p.id === cur) ?? null\n\n  function send(path: string) {\n    if (!canSend) return\n    pushRecent({ kind: 'sticker', path })\n    onSend(path)\n  }\n\n  async function onFiles(files: FileList | null) {\n    const list = Array.from(files ?? [])\n    if (fileRef.current) fileRef.current.value = ''\n    if (list.length === 0) return\n    setBusy(true); setErr(null)\n    try {\n      for (const f of list) {\n        const a = await addSticker(f, 'sticker')\n        setMine((prev) => [a, ...prev.filter((x) => x.id !== a.id)])\n      }\n    } catch (e) { setErr(friendlyStickerError(errMsg(e))) } finally { setBusy(false) }\n  }\n\n  async function remove(s: UserSticker) {\n    setMine((prev) => prev.filter((x) => x.id !== s.id))\n    try { await removeSticker(s.id) } catch { setMine((prev) => [s, ...prev]) }\n  }\n\n  const tile = (path: string, key: string, del?: UserSticker) => (\n    <div key={key} className=\"group relative\">\n      <button type=\"button\" disabled={!canSend} onClick={() => send(path)} title={canSend ? 'Отправить' : 'Нельзя писать'}\n        className=\"block aspect-square w-full rounded-xl bg-surface/60 p-1 transition hover:bg-surface disabled:opacity-50\">\n        <img src={stickerUrl(path)} alt=\"\" loading=\"lazy\" draggable={false} className=\"h-full w-full object-contain\" />\n      </button>\n      {del && (\n        <button type=\"button\" title=\"Удалить из избранных\" onClick={() => void remove(del)}\n          className=\"absolute right-1 top-1 flex h-5 w-5 items-center justify-center rounded-full bg-bg2/90 text-muted opacity-0 transition hover:text-pink group-hover:opacity-100 max-md:opacity-70\"><X size={12} /></button>\n      )}\n    </div>\n  )\n\n  const barBtn = (active: boolean) =>\n    `flex h-9 w-9 shrink-0 items-center justify-center overflow-hidden rounded-xl transition ${active ? 'bg-surface text-accent ring-1 ring-accent' : 'text-muted hover:bg-surface hover:text-text'}`\n\n  const heading = cur === 'recent' ? 'Недавние' : cur === 'mine' ? 'Избранные' : pack?.title ?? ''\n\n  return (\n    <>\n      <div className=\"min-h-0 flex-1 overflow-y-auto px-3 pb-3\">\n        <div className=\"flex items-center justify-between gap-2 pb-1 pt-3\">\n          <h4 className=\"min-w-0 truncate text-xs text-muted\">{heading}</h4>\n          <button type=\"button\" onClick={() => setManage(true)}\n            className=\"flex shrink-0 items-center gap-1 rounded-lg px-1.5 py-0.5 text-xs text-muted transition hover:bg-surface hover:text-text\"><Settings2 size={12} />Наборы</button>\n        </div>\n        {err && <p className=\"pb-2 text-xs text-pink\">{err}</p>}\n        <input ref={fileRef} type=\"file\" multiple accept=\"image/png,image/webp,image/gif,image/jpeg\" className=\"hidden\" onChange={(e) => void onFiles(e.target.files)} />\n        <div className=\"grid grid-cols-4 gap-1.5\">\n          {cur === 'mine' && (\n            <button type=\"button\" disabled={busy} onClick={() => fileRef.current?.click()}\n              className=\"flex aspect-square flex-col items-center justify-center gap-1 rounded-xl border border-dashed border-line text-xs text-muted transition hover:border-accent hover:text-accent disabled:opacity-60\">\n              {busy ? <Loader2 size={20} className=\"animate-spin\" /> : <Plus size={20} />}Добавить\n            </button>\n          )}\n          {cur === 'recent' && recent.slice(0, 24).map((r) => tile(r.path, `r${r.path}`))}\n          {cur === 'mine' && mine.map((s) => tile(s.path, s.id, s))}\n          {pack && pack.items.map((i) => tile(i.path, i.id))}\n        </div>\n        {loaded && cur === 'recent' && recent.length === 0 && (\n          <p className=\"pt-6 text-center text-xs leading-relaxed text-muted\">Здесь будут недавно отправленные стикеры.</p>\n        )}\n        {loaded && cur === 'mine' && mine.length === 0 && (\n          <p className=\"pt-4 text-center text-xs leading-relaxed text-muted\">Добавьте PNG или WebP или нажмите «+» на стикере в чате.</p>\n        )}\n        {loaded && pack && pack.items.length === 0 && (\n          <p className=\"pt-6 text-center text-xs leading-relaxed text-muted\">В наборе пока пусто. Добавьте стикеры через «Наборы».</p>\n        )}\n        {loaded && packsErr && (\n          <p className=\"pt-4 text-center text-xs leading-relaxed text-muted\">Наборы не загрузились. Выполните SQL 0017 в Supabase.</p>\n        )}\n      </div>\n      <div className=\"flex shrink-0 items-center gap-1 overflow-x-auto border-t border-line px-2 py-1.5\">\n        <button type=\"button\" title=\"Управление наборами\" onClick={() => setManage(true)} className={barBtn(false)}><Plus size={18} /></button>\n        <button type=\"button\" title=\"Недавние\" onClick={() => setSel('recent')} className={barBtn(cur === 'recent')}><Clock size={18} /></button>\n        <button type=\"button\" title=\"Избранные\" onClick={() => setSel('mine')} className={barBtn(cur === 'mine')}><Star size={18} /></button>\n        {packs.map((p) => (\n          <button key={p.id} type=\"button\" title={p.title} onClick={() => setSel(p.id)} className={barBtn(cur === p.id)}>\n            {p.items[0]\n              ? <img src={stickerUrl(p.items[0].path)} alt=\"\" className=\"h-full w-full object-contain p-0.5\" />\n              : <span className=\"text-sm font-semibold\">{p.title.slice(0, 1).toUpperCase()}</span>}\n          </button>\n        ))}\n      </div>\n      {manage && <PackManager onClose={() => { setManage(false); void load() }} />}\n    </>\n  )\n}\n","src/features/stickers/StickerView.tsx":"import { useState } from 'react'\nimport { Check, Plus } from 'lucide-react'\nimport { friendlyStickerError, saveFromMessage, stickerUrl, type StickerKind } from './stickers'\nimport { packByPath, type PackInfo } from './packs'\nimport PackPreview from './PackPreview'\n\n// Стикер или GIF внутри сообщения. «+» — в свою коллекцию; клик по стикеру из набора открывает набор.\nexport default function StickerView({ path, kind, disabled }: { path: string; kind: StickerKind; disabled?: boolean }) {\n  const [state, setState] = useState<'idle' | 'busy' | 'done' | 'err'>('idle')\n  const [info, setInfo] = useState<PackInfo | null>(null)\n\n  async function save() {\n    if (state === 'busy' || state === 'done') return\n    setState('busy')\n    try { await saveFromMessage(path, kind); setState('done') }\n    catch (e) { console.warn(friendlyStickerError(e instanceof Error ? e.message : String(e))); setState('err') }\n  }\n\n  async function openPack() {\n    if (kind !== 'sticker' || disabled) return\n    try { const i = await packByPath(path); if (i) setInfo(i) } catch { /* наборы не настроены — ничего не делаем */ }\n  }\n\n  return (\n    <div className=\"group relative inline-block\">\n      <img src={stickerUrl(path)} alt={kind === 'gif' ? 'GIF' : 'Стикер'} loading=\"lazy\" draggable={false}\n        onClick={(e) => { if (kind === 'sticker' && !disabled) { e.stopPropagation(); void openPack() } }}\n        className={`${kind === 'sticker' && !disabled ? 'cursor-pointer ' : ''}${kind === 'gif'\n          ? 'block max-h-64 max-w-[16rem] rounded-xl object-cover'\n          : 'block h-40 w-40 object-contain md:h-44 md:w-44'}`} />\n      {!disabled && (\n        <button type=\"button\" title={state === 'done' ? 'Добавлено в мои' : state === 'err' ? 'Не удалось добавить' : 'Добавить в мои'}\n          onClick={(e) => { e.stopPropagation(); void save() }}\n          className={`absolute right-1 top-1 flex h-7 w-7 items-center justify-center rounded-full border border-line bg-bg2/90 text-text shadow transition hover:text-accent ${\n            state === 'idle' || state === 'err' ? 'opacity-0 group-hover:opacity-100 max-md:opacity-70' : 'opacity-100'}`}>\n          {state === 'done' ? <Check size={14} className=\"text-accent\" /> : <Plus size={14} className={state === 'busy' ? 'animate-pulse' : ''} />}\n        </button>\n      )}\n      {info && <PackPreview info={info} onClose={() => setInfo(null)} />}\n    </div>\n  )\n}\n","src/features/stickers/EmojiPanel.tsx":"import { useEffect, useRef, useState } from 'react'\nimport { Clock, Loader2, Plus, Smile, Sticker, X, Film } from 'lucide-react'\nimport StickerTab from './StickerTab'\nimport { EMOJI_GROUPS, getRecentEmoji, pushRecentEmoji } from './emoji'\nimport {\n  addSticker, friendlyStickerError, getRecent, listMine, pushRecent, removeSticker, stickerUrl,\n  type StickerKind, type UserSticker,\n} from './stickers'\n\ntype Tab = 'emoji' | 'sticker' | 'gif'\n\ninterface Props {\n  canSend: boolean\n  onEmoji: (e: string) => void\n  onSend: (kind: StickerKind, path: string) => void\n  onClose: () => void\n}\n\nconst TABS: { id: Tab; title: string; Icon: typeof Smile }[] = [\n  { id: 'emoji', title: 'Эмодзи', Icon: Smile },\n  { id: 'sticker', title: 'Стикеры', Icon: Sticker },\n  { id: 'gif', title: 'GIF', Icon: Film },\n]\n\nexport default function EmojiPanel({ canSend, onEmoji, onSend, onClose }: Props) {\n  const [tab, setTab] = useState<Tab>('emoji')\n  const [recentEmoji, setRecentEmoji] = useState<string[]>(() => getRecentEmoji())\n  const [mine, setMine] = useState<UserSticker[]>([])\n  const [loaded, setLoaded] = useState(false)\n  const [busy, setBusy] = useState(false)\n  const [err, setErr] = useState<string | null>(null)\n  const rootRef = useRef<HTMLDivElement>(null)\n  const fileRef = useRef<HTMLInputElement>(null)\n  const scrollRef = useRef<HTMLDivElement>(null)\n\n  useEffect(() => {\n    let alive = true\n    void listMine().then((l) => { if (alive) { setMine(l); setLoaded(true) } })\n      .catch(() => { if (alive) setLoaded(true) })\n    return () => { alive = false }\n  }, [])\n\n  useEffect(() => {\n    const onDown = (e: MouseEvent | TouchEvent) => {\n      const t = e.target as Node | null\n      if (!t || rootRef.current?.contains(t)) return\n      if (t instanceof Element && t.closest('[data-emoji-toggle], [data-sticker-modal]')) return\n      onClose()\n    }\n    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose() }\n    document.addEventListener('mousedown', onDown)\n    document.addEventListener('touchstart', onDown)\n    document.addEventListener('keydown', onKey)\n    return () => {\n      document.removeEventListener('mousedown', onDown)\n      document.removeEventListener('touchstart', onDown)\n      document.removeEventListener('keydown', onKey)\n    }\n  }, [onClose])\n\n  function pickEmoji(e: string) {\n    setRecentEmoji(pushRecentEmoji(e))\n    onEmoji(e)\n  }\n\n  function send(kind: StickerKind, path: string) {\n    if (!canSend) return\n    pushRecent({ kind, path })\n    onSend(kind, path)\n  }\n\n  async function onFiles(files: FileList | null, kind: StickerKind) {\n    const list = Array.from(files ?? [])\n    if (fileRef.current) fileRef.current.value = ''\n    if (list.length === 0) return\n    setBusy(true); setErr(null)\n    try {\n      for (const f of list) {\n        const added = await addSticker(f, kind)\n        setMine((prev) => [added, ...prev.filter((x) => x.id !== added.id)])\n      }\n    } catch (e) {\n      setErr(friendlyStickerError(e instanceof Error ? e.message : (e as { message?: string })?.message ?? 'Не удалось загрузить'))\n    } finally { setBusy(false) }\n  }\n\n  async function remove(s: UserSticker) {\n    setMine((prev) => prev.filter((x) => x.id !== s.id))\n    try { await removeSticker(s.id) } catch { setMine((prev) => [s, ...prev]) }\n  }\n\n  function jump(id: string) {\n    const el = scrollRef.current?.querySelector(`[data-group=\"${id}\"]`)\n    if (el instanceof HTMLElement && scrollRef.current) scrollRef.current.scrollTo({ top: el.offsetTop - 4, behavior: 'smooth' })\n  }\n\n  const kind: StickerKind = 'gif'\n  const items = mine.filter((s) => s.kind === kind)\n  const recent = tab === 'emoji' ? [] : getRecent(kind)\n\n  const tile = (s: { path: string }, key: string, id?: UserSticker) => (\n    <div key={key} className=\"group relative\">\n      <button type=\"button\" disabled={!canSend} onClick={() => send(kind, s.path)} title={canSend ? 'Отправить' : 'Нельзя писать'}\n        className={`block w-full overflow-hidden rounded-xl bg-surface/60 transition hover:bg-surface disabled:opacity-50 ${kind === 'gif' ? 'aspect-[4/3]' : 'aspect-square p-1'}`}>\n        <img src={stickerUrl(s.path)} alt=\"\" loading=\"lazy\" draggable={false}\n          className={`h-full w-full ${kind === 'gif' ? 'object-cover' : 'object-contain'}`} />\n      </button>\n      {id && (\n        <button type=\"button\" title=\"Удалить из моих\" onClick={() => void remove(id)}\n          className=\"absolute right-1 top-1 flex h-5 w-5 items-center justify-center rounded-full bg-bg2/90 text-muted opacity-0 transition hover:text-pink group-hover:opacity-100 max-md:opacity-70\">\n          <X size={12} />\n        </button>\n      )}\n    </div>\n  )\n\n  return (\n    <div ref={rootRef}\n      className=\"absolute bottom-full left-3 right-3 z-30 mb-2 flex h-[22rem] max-h-[55vh] flex-col overflow-hidden rounded-3xl border border-line bg-bg2 shadow-2xl md:right-auto md:w-[24rem]\">\n      <div className=\"flex shrink-0 gap-1 border-b border-line p-2\">\n        {TABS.map(({ id, title, Icon }) => (\n          <button key={id} type=\"button\" onClick={() => { setTab(id); setErr(null) }}\n            className={`flex flex-1 items-center justify-center gap-1.5 rounded-2xl px-3 py-1.5 text-sm font-medium transition ${\n              tab === id ? 'bg-accent text-on-accent' : 'text-muted hover:bg-surface hover:text-text'}`}>\n            <Icon size={16} />{title}\n          </button>\n        ))}\n      </div>\n\n      {tab === 'emoji' ? (\n        <>\n          <div ref={scrollRef} className=\"relative min-h-0 flex-1 overflow-y-auto px-3 pb-2\">\n            {recentEmoji.length > 0 && (\n              <section data-group=\"recent\">\n                <h4 className=\"flex items-center gap-1 pb-1 pt-3 text-xs text-muted\"><Clock size={12} />Недавние</h4>\n                <div className=\"grid grid-cols-8 gap-0.5\">\n                  {recentEmoji.map((e) => <EmojiBtn key={`r${e}`} e={e} onPick={pickEmoji} />)}\n                </div>\n              </section>\n            )}\n            {EMOJI_GROUPS.map((g) => (\n              <section key={g.id} data-group={g.id}>\n                <h4 className=\"pb-1 pt-3 text-xs text-muted\">{g.title}</h4>\n                <div className=\"grid grid-cols-8 gap-0.5\">\n                  {g.items.map((e) => <EmojiBtn key={e} e={e} onPick={pickEmoji} />)}\n                </div>\n              </section>\n            ))}\n          </div>\n          <div className=\"flex shrink-0 justify-between gap-1 border-t border-line px-2 py-1.5\">\n            {EMOJI_GROUPS.map((g) => (\n              <button key={g.id} type=\"button\" title={g.title} onClick={() => jump(g.id)}\n                className=\"flex h-8 w-8 items-center justify-center rounded-xl text-lg opacity-70 transition hover:bg-surface hover:opacity-100\">\n                {g.items[0]}\n              </button>\n            ))}\n          </div>\n        </>\n      ) : tab === 'sticker' ? (\n        <StickerTab canSend={canSend} onSend={(p) => onSend('sticker', p)} />\n      ) : (\n        <div className=\"min-h-0 flex-1 overflow-y-auto px-3 pb-3\">\n          <input ref={fileRef} type=\"file\" multiple className=\"hidden\"\n            accept={tab === 'gif' ? 'image/gif' : 'image/png,image/webp,image/gif,image/jpeg'}\n            onChange={(e) => void onFiles(e.target.files, kind)} />\n          {err && <p className=\"pt-3 text-xs text-pink\">{err}</p>}\n          {recent.length > 0 && (\n            <section>\n              <h4 className=\"flex items-center gap-1 pb-1 pt-3 text-xs text-muted\"><Clock size={12} />Недавние</h4>\n              <div className={`grid gap-1.5 ${kind === 'gif' ? 'grid-cols-3' : 'grid-cols-4'}`}>\n                {recent.slice(0, kind === 'gif' ? 6 : 8).map((r) => tile(r, `r${r.path}`))}\n              </div>\n            </section>\n          )}\n          <h4 className=\"pb-1 pt-3 text-xs text-muted\">{kind === 'gif' ? 'Мои GIF' : 'Мои стикеры'}</h4>\n          <div className={`grid gap-1.5 ${kind === 'gif' ? 'grid-cols-3' : 'grid-cols-4'}`}>\n            <button type=\"button\" disabled={busy} onClick={() => fileRef.current?.click()}\n              className={`flex flex-col items-center justify-center gap-1 rounded-xl border border-dashed border-line text-xs text-muted transition hover:border-accent hover:text-accent disabled:opacity-60 ${kind === 'gif' ? 'aspect-[4/3]' : 'aspect-square'}`}>\n              {busy ? <Loader2 size={20} className=\"animate-spin\" /> : <Plus size={20} />}\n              Добавить\n            </button>\n            {items.map((s) => tile(s, s.id, s))}\n          </div>\n          {loaded && items.length === 0 && (\n            <p className=\"pt-4 text-center text-xs leading-relaxed text-muted\">\n              {kind === 'gif'\n                ? 'Загрузите GIF или нажмите «+» на гифке в чате, чтобы сохранить её сюда.'\n                : 'Добавьте PNG или WebP с прозрачным фоном или нажмите «+» на стикере в чате.'}\n            </p>\n          )}\n        </div>\n      )}\n    </div>\n  )\n}\n\nfunction EmojiBtn({ e, onPick }: { e: string; onPick: (e: string) => void }) {\n  return (\n    <button type=\"button\" onClick={() => onPick(e)}\n      className=\"flex h-9 items-center justify-center rounded-xl text-2xl transition hover:bg-surface\">{e}</button>\n  )\n}\n","supabase/migrations/0017_sticker_packs.sql":"-- Sunset: наборы стикеров (свои + добавленные от других пользователей).\n\ncreate table if not exists public.sticker_packs (\n  id uuid primary key default gen_random_uuid(),\n  owner_id uuid not null default auth.uid() references public.profiles(id) on delete cascade,\n  title text not null check (char_length(btrim(title)) between 1 and 40),\n  short_code text not null unique default substr(replace(gen_random_uuid()::text, '-', ''), 1, 12),\n  created_at timestamptz not null default now()\n);\ncreate index if not exists sticker_packs_owner_idx on public.sticker_packs (owner_id, created_at);\n\ncreate table if not exists public.sticker_pack_items (\n  id uuid primary key default gen_random_uuid(),\n  pack_id uuid not null references public.sticker_packs(id) on delete cascade,\n  path text not null check (path ~ '^[0-9a-f-]{36}/[A-Za-z0-9._-]{1,120}$'),\n  position int not null default 0,\n  created_at timestamptz not null default now(),\n  unique (pack_id, path)\n);\ncreate index if not exists sticker_pack_items_path_idx on public.sticker_pack_items (path);\n\ncreate table if not exists public.sticker_pack_subs (\n  user_id uuid not null default auth.uid() references public.profiles(id) on delete cascade,\n  pack_id uuid not null references public.sticker_packs(id) on delete cascade,\n  created_at timestamptz not null default now(),\n  primary key (user_id, pack_id)\n);\n\nalter table public.sticker_packs enable row level security;\nalter table public.sticker_pack_items enable row level security;\nalter table public.sticker_pack_subs enable row level security;\n\ndrop policy if exists sticker_packs_select on public.sticker_packs;\ndrop policy if exists sticker_packs_insert on public.sticker_packs;\ndrop policy if exists sticker_packs_update on public.sticker_packs;\ndrop policy if exists sticker_packs_delete on public.sticker_packs;\ncreate policy sticker_packs_select on public.sticker_packs for select to authenticated\n  using (owner_id = auth.uid() or exists (select 1 from public.sticker_pack_subs s where s.pack_id = id and s.user_id = auth.uid()));\ncreate policy sticker_packs_insert on public.sticker_packs for insert to authenticated with check (owner_id = auth.uid());\ncreate policy sticker_packs_update on public.sticker_packs for update to authenticated using (owner_id = auth.uid()) with check (owner_id = auth.uid());\ncreate policy sticker_packs_delete on public.sticker_packs for delete to authenticated using (owner_id = auth.uid());\n\ndrop policy if exists sticker_items_select on public.sticker_pack_items;\ndrop policy if exists sticker_items_insert on public.sticker_pack_items;\ndrop policy if exists sticker_items_delete on public.sticker_pack_items;\ncreate policy sticker_items_select on public.sticker_pack_items for select to authenticated\n  using (exists (select 1 from public.sticker_packs p where p.id = pack_id));\ncreate policy sticker_items_insert on public.sticker_pack_items for insert to authenticated\n  with check (exists (select 1 from public.sticker_packs p where p.id = pack_id and p.owner_id = auth.uid()));\ncreate policy sticker_items_delete on public.sticker_pack_items for delete to authenticated\n  using (exists (select 1 from public.sticker_packs p where p.id = pack_id and p.owner_id = auth.uid()));\n\ndrop policy if exists sticker_subs_select on public.sticker_pack_subs;\ndrop policy if exists sticker_subs_delete on public.sticker_pack_subs;\ncreate policy sticker_subs_select on public.sticker_pack_subs for select to authenticated using (user_id = auth.uid());\ncreate policy sticker_subs_delete on public.sticker_pack_subs for delete to authenticated using (user_id = auth.uid());\n\nrevoke all on public.sticker_packs, public.sticker_pack_items, public.sticker_pack_subs from anon;\nrevoke all on public.sticker_packs, public.sticker_pack_items, public.sticker_pack_subs from authenticated;\ngrant select, insert, delete on public.sticker_packs to authenticated;\ngrant update (title) on public.sticker_packs to authenticated;\ngrant select, insert, delete on public.sticker_pack_items to authenticated;\ngrant select, delete on public.sticker_pack_subs to authenticated;\n\n-- Лимиты: 20 наборов на человека, 120 стикеров в наборе, 200 добавленных наборов.\ncreate or replace function public.sticker_packs_limits() returns trigger\nlanguage plpgsql security definer set search_path = '' as $$\nbegin\n  if tg_table_name = 'sticker_packs' then\n    if (select count(*) from public.sticker_packs where owner_id = new.owner_id) >= 20 then raise exception 'pack limit'; end if;\n  elsif tg_table_name = 'sticker_pack_items' then\n    if (select count(*) from public.sticker_pack_items where pack_id = new.pack_id) >= 120 then raise exception 'item limit'; end if;\n  else\n    if (select count(*) from public.sticker_pack_subs where user_id = new.user_id) >= 200 then raise exception 'sub limit'; end if;\n  end if;\n  return new;\nend $$;\ndrop trigger if exists sticker_packs_limit on public.sticker_packs;\ncreate trigger sticker_packs_limit before insert on public.sticker_packs for each row execute function public.sticker_packs_limits();\ndrop trigger if exists sticker_items_limit on public.sticker_pack_items;\ncreate trigger sticker_items_limit before insert on public.sticker_pack_items for each row execute function public.sticker_packs_limits();\ndrop trigger if exists sticker_subs_limit on public.sticker_pack_subs;\ncreate trigger sticker_subs_limit before insert on public.sticker_pack_subs for each row execute function public.sticker_packs_limits();\n\n-- Описание набора для просмотра (внутренняя функция).\ncreate or replace function public.pack_json(p_id uuid) returns jsonb\nlanguage sql stable security definer set search_path = '' as $$\n  select jsonb_build_object(\n    'id', p.id, 'title', p.title, 'code', p.short_code,\n    'owner_name', (select pr.display_name from public.profiles pr where pr.id = p.owner_id),\n    'mine', p.owner_id = auth.uid(),\n    'subscribed', exists (select 1 from public.sticker_pack_subs s where s.pack_id = p.id and s.user_id = auth.uid()),\n    'items', coalesce((select jsonb_agg(i.path order by i.position, i.created_at) from public.sticker_pack_items i where i.pack_id = p.id), '[]'::jsonb))\n  from public.sticker_packs p where p.id = p_id\n$$;\nrevoke all on function public.pack_json(uuid) from public, anon, authenticated;\n\ncreate or replace function public.pack_by_code(p_code text) returns jsonb\nlanguage plpgsql stable security definer set search_path = '' as $$\ndeclare v uuid;\nbegin\n  if auth.uid() is null then raise exception 'not authenticated'; end if;\n  select id into v from public.sticker_packs where short_code = lower(btrim(p_code));\n  if v is null then return null; end if;\n  return public.pack_json(v);\nend $$;\n\ncreate or replace function public.pack_by_path(p_path text) returns jsonb\nlanguage plpgsql stable security definer set search_path = '' as $$\ndeclare v uuid;\nbegin\n  if auth.uid() is null then raise exception 'not authenticated'; end if;\n  select pack_id into v from public.sticker_pack_items where path = p_path order by created_at limit 1;\n  if v is null then return null; end if;\n  return public.pack_json(v);\nend $$;\n\ncreate or replace function public.subscribe_pack(p_code text) returns jsonb\nlanguage plpgsql security definer set search_path = '' as $$\ndeclare v uuid; o uuid;\nbegin\n  if auth.uid() is null then raise exception 'not authenticated'; end if;\n  select id, owner_id into v, o from public.sticker_packs where short_code = lower(btrim(p_code));\n  if v is null then raise exception 'pack not found'; end if;\n  if o <> auth.uid() then\n    insert into public.sticker_pack_subs (user_id, pack_id) values (auth.uid(), v) on conflict do nothing;\n  end if;\n  return public.pack_json(v);\nend $$;\n\nrevoke all on function public.pack_by_code(text), public.pack_by_path(text), public.subscribe_pack(text) from public, anon;\ngrant execute on function public.pack_by_code(text), public.pack_by_path(text), public.subscribe_pack(text) to authenticated;\n\nnotify pgrst, 'reload schema';\n"}
const STK = 'src/features/stickers/stickers.ts'
if (!existsSync('package.json') || !existsSync(STK) || !existsSync('src/features/stickers/EmojiPanel.tsx')) {
  console.error('Сначала примени setup41.mjs (панель стикеров). Запускай из папки проекта (sunset-app).')
  process.exit(1)
}
if (existsSync('src/features/stickers/packs.ts')) { console.log('Уже применено'); process.exit(0) }
const raw = readFileSync(STK, 'utf8')
const crlf = raw.includes('\r\n')
let s = raw.replace(/\r\n/g, '\n')
if (!s.includes('export async function shrink(')) {
  if (s.split('async function shrink(').length !== 2) { console.error('Ничего не изменено: не найден shrink в stickers.ts'); process.exit(1) }
  s = s.replace('async function shrink(', () => 'export async function shrink(')
}
writeFileSync(STK, crlf ? s.replace(/\n/g, '\r\n') : s)
console.log('обновлён ' + STK)
for (const [file, content] of Object.entries(newFiles)) {
  mkdirSync(dirname(file), { recursive: true })
  writeFileSync(file, content)
  console.log('записан ' + file)
}
console.log('Готово: наборы стикеров. Не забудь SQL 0017, затем: npm run build')
